// サブコマンド check が、資料ごとのスクリプト deck.ts を eslint で検査するときに渡す設定 (計画の KTD4・KTD8)。
// 規則は、プラグインのコードの設定 (ファイル eslint.config.mjs) と同じ tseslint.configs.strictTypeChecked にする。
// プラグインのディレクトリには node_modules が無いので、この設定ファイルからの import では @eslint/js と typescript-eslint を読み込めない。
// そのため、check が環境変数 SLIDE_DECK_NODE_MODULES に指定したキャッシュの node_modules から、場所を明示して読み込む。
// 型の情報には、check が書いた資料のディレクトリの build/tsconfig.json (環境変数 SLIDE_DECK_TSCONFIG) を使う。
// projectService は検査するファイルから上のディレクトリの tsconfig.json を使い、下にある build/tsconfig.json を使わないので使わない。

import { createRequire } from "node:module";
import { dirname, join } from "node:path";

const nodeModules = process.env["SLIDE_DECK_NODE_MODULES"];
const tsconfig = process.env["SLIDE_DECK_TSCONFIG"];
if (nodeModules === undefined || nodeModules === "" || tsconfig === undefined || tsconfig === "") {
  throw new Error(
    "環境変数 SLIDE_DECK_NODE_MODULES と SLIDE_DECK_TSCONFIG が無い。この設定ファイルは、サブコマンド check が eslint に渡すためのもの",
  );
}

const require = createRequire(join(nodeModules, "slide-deck-eslint-config.cjs"));
const { defineConfig } = require("eslint/config");
const js = require("@eslint/js");
const tseslint = require("typescript-eslint");

export default defineConfig({
  files: ["**/*.ts"],
  extends: [js.configs.recommended, tseslint.configs.strictTypeChecked],
  languageOptions: {
    parserOptions: {
      projectService: false,
      project: tsconfig,
      tsconfigRootDir: dirname(tsconfig),
    },
  },
});
// サブコマンド check と pptx のテストの補助 (計画の U5 の Approach 7)。
// 一時的なディレクトリに、次の 3 つを作る。
// - プラグインのディレクトリのコピー。node_modules を持たないので、ライブラリをキャッシュのディレクトリからしか読み込めない
//   (利用者の環境では、プラグインの展開先に node_modules が無い。計画の KTD8)。
// - キャッシュのディレクトリ (環境変数 SLIDE_DECK_CACHE_DIR)。node-<ハッシュ値>/node_modules は、
//   CI が npm ci で入れたファイル slide-deck/node_modules へのシンボリックリンクにする。
//   venv は、フラグファイルと、引数を記録するだけの bin/python を持つ偽物にする (CI には pptx のスキルが無いため)。
// - 資料のディレクトリ。見本の資料 examples/sample/ の outline.md と deck.ts をコピーする。

import {
  chmodSync,
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { type CachePaths, cachePaths, PLUGIN_DIR } from "../../src/setup/setup.ts";

/** 偽の pptx のスキルのディレクトリ (scripts/apply_theme.js と scripts/office/validate.py を持つ) */
export const FAKE_PPTX_SKILL = join(PLUGIN_DIR, "tests", "fixtures", "pptx-skill");

/** 偽の apply_theme.js が呼び出しを記録するファイルを指定する環境変数 */
export const FAKE_APPLY_THEME_LOG_ENV = "FAKE_APPLY_THEME_LOG";

/** 偽の bin/python の終了コードを指定する環境変数 (無ければ 0) */
export const FAKE_PYTHON_EXIT_ENV = "FAKE_PYTHON_EXIT";

// プラグインのディレクトリのうち、入口のサブコマンドが読むファイル (.claude-plugin/plugin.json は、check-outline と write-info が版を読む)
const PLUGIN_FILES = [".claude-plugin", "src", "tsconfig.json", "package.json", "package-lock.json", "uv.lock", ".python-version"];

export interface TestSandbox {
  readonly root: string;
