  copySample(relative?: string): string;
  /** 偽の bin/python の呼び出し (1 行に 1 回。引数を空白でつないだもの) */
  pythonCalls(): string[];
  /** 偽の apply_theme.js の呼び出し */
  applyThemeCalls(): ApplyThemeCall[];
  cleanup(): void;
}

